from pathlib import Path
from xml.sax.saxutils import escape
parts=['<svg xmlns="http://www.w3.org/2000/svg" width="1400" height="1040" viewBox="0 0 1400 1040"><rect width="1400" height="1040" fill="#f4f7fc"/><style>text{font-family:"Noto Sans CJK SC","Microsoft YaHei",sans-serif;fill:#173458} .title{font-size:27px;font-weight:bold}.h{font-size:21px;font-weight:bold}.t{font-size:17px}.small{font-size:15px}.wire{stroke:#2865df;stroke-width:3;fill:none}.box{fill:white;stroke:#bfcede;stroke-width:2}</style>']
def text(x,y,s,c='t'):parts.append(f'<text x="{x}" y="{y}" class="{c}">{escape(s)}</text>')
def line(x1,y1,x2,y2):parts.append(f'<path class="wire" d="M{x1},{y1} L{x2},{y2}"/>')
def rect(x,y,w,h):parts.append(f'<rect class="box" x="{x}" y="{y}" width="{w}" height="{h}" rx="9"/>')
def dot(x,y):parts.append(f'<circle cx="{x}" cy="{y}" r="5" fill="#2865df"/>')
def resistor(x,y,label):parts.append(f'<rect x="{x}" y="{y-11}" width="100" height="22" fill="#e8f0fc" stroke="#2865df" stroke-width="2"/>');text(x,y-24,label,'small')
text(40,50,'MQ-2 与 ESP 电平适配参考电路','title')
text(40,82,'连接前核验实物；禁止5V直接进入GPIO/A0。所有GND共地。','small')
rect(30,110,1340,245);text(55,148,'① ESP32 AO：10kΩ / 15kΩ，比例1.667（如ADC接近饱和可改12kΩ / 15kΩ）','h')
text(65,214,'MQ-2 AO');line(195,210,300,210);resistor(300,210,'R上 10kΩ');line(400,210,600,210);dot(520,210);line(600,210,1080,210);text(1090,216,'GPIO34 / ADC1')
line(520,210,520,250);parts.append('<rect x="509" y="250" width="22" height="45" fill="#e8f0fc" stroke="#2865df" stroke-width="2"/>');text(555,280,'R下 15kΩ');line(520,295,520,320);line(498,320,542,320);text(65,307,'5.0V → 3.0V；5.25V → 3.15V，须测量输入范围与ADC有效量程。','small')
rect(30,375,1340,235);text(55,414,'② ESP8266 AO：保守分压56kΩ / 10kΩ，比例6.6','h')
text(65,478,'MQ-2 AO');line(195,475,300,475);resistor(300,475,'R上 56kΩ');line(400,475,1080,475);dot(520,475);text(1090,481,'A0连接器')
line(520,475,520,510);parts.append('<rect x="509" y="510" width="22" height="45" fill="#e8f0fc" stroke="#2865df" stroke-width="2"/>');text(555,538,'R下 10kΩ');line(520,555,520,575);line(498,575,542,575)
text(65,588,'5.25V → 约0.795V；兼顾未知A0量程的输入保护，实际换算仍需核验板载分压与标定。','small')
rect(30,630,1340,295);text(55,670,'③ MQ DO 与低触发蜂鸣器：BSS138电平板（两个独立通道，逻辑不反相）','h')
rect(500,705,340,170);text(535,738,'BSS138 转换板','h');text(525,775,'LV=3.3V   HV=5V');text(525,809,'LV1                 HV1');text(525,846,'LV2                 HV2')
text(65,808,'ESP MQ数字输入');line(250,803,500,803);line(840,803,1050,803);text(1060,809,'MQ-2 DO')
text(65,845,'ESP 蜂鸣器GPIO');line(250,840,500,840);line(840,840,1050,840);text(1060,846,'蜂鸣器 I/O')
text(65,897,'LV2上拉10kΩ至3.3V，复位默认关闭；各侧上拉、电流与单边断电行为须实测。','small')
text(40,964,'软件对应：AO使用实际分压比例与板ADC量程；DO与蜂鸣器均保持低有效。','t')
text(40,998,'注意：图中为参考功能接线，非已完成电气验收的PCB原理图。电源、引脚及器件额定值见硬件手册。','small')
parts.append('</svg>')
Path('docs/电平转换参考.svg').write_text(''.join(parts))
